module swap_generator(input clk, input rst_n, input start, input [9:0] n, output reg valid, output reg [9:0] a_out, output reg [9:0] b_out, output reg out_valid, output reg done); reg [2:0] state; reg [31:0] current_block; reg [2:0] swap_idx; reg [3:0] cross_idx; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 3'd0; current_block <= 32'd0; swap_idx <= 32'd0; cross_idx <= 32'd0; valid <= 1'b0; a_out <= 32'd0; b_out <= 32'd0; out_valid <= 1'b0; done <= 1'b0; end else begin if (state == 3'd0) begin if (start) begin if ((n % 4) == 0 || (n % 4) == 1) begin state <= 3'd2; current_block <= 32'd0; swap_idx <= 32'd0; valid <= 1'b1; done <= 1'b0; end else begin state <= 3'd4; valid <= 1'b0; done <= 1'b1; end end end else if (state == 3'd2) begin if (swap_idx < 6) begin case (swap_idx) 0: a_out = current_block; b_out = current_block + 2; 1: a_out = current_block + 1; b_out = current_block + 3; 2: a_out = current_block; b_out = current_block + 1; 3: a_out = current_block + 2; b_out = current_block + 3; 4: a_out = current_block; b_out = current_block + 3; 5: a_out = current_block + 1; b_out = current_block + 2; default: a_out = 32'd0; b_out = 32'd0; endcase out_valid <= 1'b1; swap_idx <= swap_idx + 1; end else begin if (n % 4 == 1) begin state <= 3'd3; cross_idx <= 32'd0; end else begin if (current_block + 4 > n - 1) begin state <= 3'd4; done <= 1'b1; end else begin state <= 3'd2; current_block <= current_block + 4; swap_idx <= 32'd0; end end end end else if (state == 3'd3) begin if (cross_idx < 4) begin a_out = 32'd0; b_out = current_block + cross_idx; if (b_out < n && a_out < b_out) begin out_valid <= 1'b1; end else begin out_valid <= 1'b0; end cross_idx <= cross_idx + 1; end else begin if (current_block + 4 > n - 1) begin state <= 3'd4; done <= 1'b1; end else begin state <= 3'd2; current_block <= current_block + 4; swap_idx <= 32'd0; cross_idx <= 32'd0; end end end endmodule